python3 -c "
from itertools import combinations

elements = ['e', 'x3', 'x1', 'x2']
# 乘法表: table[a][b] = a*b
idx = {name: i for i, name in enumerate(elements)}
table = [
    ['e', 'x3', 'x1', 'x2'],   # e *
    ['x3', 'e', 'x2', 'x1'],   # x3 *
    ['x1', 'x2', 'e', 'x3'],   # x1 *
    ['x2', 'x1', 'x3', 'e'],   # x2 *
]

def mul(a, b):
    return table[idx[a]][idx[b]]

# 检查每个元素的阶
for a in elements:
    power = a
    for k in range(1, 5):
        if power == 'e':
            print(f'{a} 的阶 = {k}')
            break
        power = mul(power, a)

# 枚举所有子集，检查是否为子群
print()
print('所有子群:')
for r in range(1, 5):
    for subset in combinations(elements, r):
        S = set(subset)
        if 'e' not in S:
            continue
        closed = True
        for a in S:
            for b in S:
                if mul(a, b) not in S:
                    closed = False
                    break
            if not closed:
                break
        if closed:
            print(f'  {sorted(S)}')
"

